package com.vitalminds.service;
import com.vitalminds.model.*; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.apache.pdfbox.pdmodel.common.PDRectangle; import org.apache.pdfbox.pdmodel.PDPageContentStream; import org.springframework.stereotype.Service; import java.io.*; import java.util.*;
@Service public class HealthSummaryService {
 public byte[] create(User u,HealthRecord r,int score,List<String> recs)throws IOException{try(ByteArrayOutputStream out=new ByteArrayOutputStream();PDDocument doc=new PDDocument()){PDPage page=new PDPage(PDRectangle.A4);doc.addPage(page);try(PDPageContentStream c=new PDPageContentStream(doc,page)){c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),22);c.beginText();c.newLineAtOffset(50,760);c.showText("VitalMinds Health Summary");c.endText();c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11);float y=725;String[] lines={"Name: "+u.getName(),"Email: "+u.getEmail(),"Vital Score: "+score+" / 100","Goal: "+safe(u.getGoal()),"Weight: "+val(u.getWeightKg(),"kg"),"Height: "+val(u.getHeightCm(),"cm"),"","Latest report: "+(r==null?"No report uploaded":r.getFileName()),"Hemoglobin: "+val(r==null?null:r.getHemoglobin(),"g/dL"),"Glucose: "+val(r==null?null:r.getGlucose(),"mg/dL"),"Cholesterol: "+val(r==null?null:r.getCholesterol(),"mg/dL"),"Blood pressure: "+bp(r),"BMI: "+val(r==null?null:r.getBmi(),"")}; for(String line:lines){c.beginText();c.newLineAtOffset(50,y);c.showText(line);c.endText();y-=20;} y-=10;c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),13);c.beginText();c.newLineAtOffset(50,y);c.showText("Wellness suggestions");c.endText();y-=20;c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),10);for(String s:recs){String t="• "+s;for(String part:wrap(t,95)){c.beginText();c.newLineAtOffset(50,y);c.showText(part);c.endText();y-=15;if(y<60){c.close();page=new PDPage(PDRectangle.A4);doc.addPage(page);y=760;}}}y-=8;c.beginText();c.newLineAtOffset(50,Math.max(40,y));c.showText("Educational wellness summary only; not a medical diagnosis.");c.endText();}doc.save(out);return out.toByteArray();}}
 private String safe(String s){return s==null?"Not set":s;} private String val(Object x,String unit){return x==null?"Not detected":x+" "+unit;} private String bp(HealthRecord r){return r==null||r.getSystolic()==null?"Not detected":r.getSystolic()+"/"+r.getDiastolic()+" mmHg";} private List<String> wrap(String s,int n){List<String> o=new ArrayList<>();while(s.length()>n){int p=s.lastIndexOf(' ',n);if(p<1)p=n;o.add(s.substring(0,p));s=s.substring(p+1);}if(!s.isBlank())o.add(s);return o;}
}
